from collections import deque

def comps(g, val=0):
 R,C=len(g),len(g[0]); seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]!=val or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); co=[]
   while q:
    a,b=q.pop(); co.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<R and 0<=y<C and g[x][y]==val and (x,y) not in seen: seen.add((x,y));q.append((x,y))
   out.append(co)
 return out
